import requests
import sys
import re

def process_line(line):
    parts = line.strip().split('\t')
    if len(parts) != 4:
        return None
    amount, from_currency, to_currency, template = parts
    try:
        amount_float = float(amount)
    except ValueError:
        return None

    try:
        response = requests.get(f'https://open.er-api.com/v6/latest/{from_currency}')
        response.raise_for_status()
        data = response.json()
        if to_currency not in data['rates']:
            return None
        rate = data['rates'][to_currency]
    except (requests.RequestException, KeyError):
        return None

    def evaluate_expression(expr):
        try:
            return round(float(expr.replace('amount', str(amount_float)).replace('rate', str(rate))), 2)
        except:
            return 0.0

    def replace_placeholders(text):
        return re.sub(r'\{\{([^}]+)\}\}', evaluate_expression, text)

    return replace_placeholders(template)

def main():
    if len(sys.argv) != 2:
        print("Usage: python currency_template.py <input_file>")
        return

    input_file = sys.argv[1]
    try:
        with open(input_file, 'r') as f:
            for line in f:
                if not line.strip():
                    continue
                result = process_line(line)
                if result is not None:
                    print(result)
    except IOError:
        print("ERROR\t" + sys.argv[1])

if __name__ == "__main__":
    main()
